use cuda_device::{kernel, launch_bounds, launch_contract, thread, DisjointSlice};
use cuda_host::cuda_module;
use cuda_core::{CudaContext, DeviceBuffer, LaunchConfig1D};

// === 设备端代码 —— 这里的一切都会被编译为 PTX ===
// 该宏还会在下方生成主机端 API：
// `load`、`prepare_vecadd`，以及安全的 `vecadd` 启动方法。
#[cuda_module]
mod kernels {
    use super::*;

    #[kernel] // GPU 入口点
    #[launch_bounds(256)] // 每个线程块的最大线程数；让编译器据此预算寄存器
    #[launch_contract(domain = 1, block = (256, 1, 1))] // 以 1 维索引、256 线程的块运行
    pub fn vecadd(a: &[f32], b: &[f32], mut c: DisjointSlice<f32>) {
        let idx = thread::index_1d();
        let idx_raw = idx.get(); // 普通的 usize，用于读取输入
        if let Some(c_elem) = c.get_mut(idx) {
            *c_elem = a[idx_raw] + b[idx_raw];
        }
    }
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    // === 主机端设置 —— 设备、流与缓冲区 ===
    let ctx = CudaContext::new(0)?;
    let stream = ctx.default_stream();

    const N: usize = 1024;
    let a_host: Vec<f32> = (0..N).map(|i| i as f32).collect();
    let b_host: Vec<f32> = (0..N).map(|i| (i * 2) as f32).collect();

    let a_dev = DeviceBuffer::from_host(&stream, &a_host)?;
    let b_dev = DeviceBuffer::from_host(&stream, &b_host)?;
    let mut c_dev = DeviceBuffer::<f32>::zeroed(&stream, N)?;

    // === 加载、准备、启动 ===
    // 安全性说明：本包拥有为上述 kernels 模块生成的内嵌设备代码束。
    let module = unsafe { kernels::load(&ctx)? };

    // 4 个线程块、每块 256 线程、0 字节动态共享内存。`prepare_vecadd` 会将
    // 该配置与上方的契约以及设备的实际限制进行校验。
    // 下面的安全 `vecadd` 方法接受该令牌，而非原始配置。
    let prepared = module.prepare_vecadd(LaunchConfig1D::new((N as u32).div_ceil(256), 256, 0))?;
    module.vecadd(&stream, &prepared, &a_dev, &b_dev, &mut c_dev)?;

    // === 读回并验证 ===
    // 该方法会拷贝数据并同步，因此到可以读取 `c_host` 时，启动已完成。
    let c_host = c_dev.to_host_vec(&stream)?;

    let errors = (0..N)
        .filter(|&i| (c_host[i] - (a_host[i] + b_host[i])).abs() > 1e-5)
        .count();

    if errors == 0 {
        println!("PASSED: all {} elements correct", N);
    } else {
        eprintln!("FAILED: {} errors", errors);
        std::process::exit(1);
    }
    Ok(())
}
```

主机端与设备端代码共存于一个文件，用一条命令即可构建，无需单独的内核 crate。
